import heapq

def shortest_path(edges, start, end):
    # If start is the same as end, return immediately
    if start == end:
        return (0, [start])

    # Validate edge weights for negativity
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")

    # Build adjacency list
    graph = {}
    all_nodes = set()
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # Handle case where start node has no outgoing edges
    if start not in graph or end not in all_nodes:
        return (None, None)

    # Initialize distances and path tracking structures
    distances = {node: float('inf') for node in all_nodes}
    distances[start] = 0
    path_map = {}
    predecessors = {}

    priority_queue = [(0, start)]

    while priority_queue:
        current_dist, current_node = heapq.heappop(priority_queue)

        if current_node in predecessors and current_dist > distances[current_node]:
            continue

        if current_node == end:
            # Reconstruct the path from end to start using predecessor map
            path = []
            node = end
            while node is not None:
                path.append(node)
                if node == start:
                    break
                node = predecessors.get(node)
            return (current_dist, path[::-1])

        for neighbor, weight in graph.get(current_node, []):
            new_dist = current_dist + weight
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                path_map[neighbor] = current_node
                predecessors[neighbor] = current_node
                heapq.heappush(priority_queue, (new_dist, neighbor))

    # No path found to end node
    return (None, None)
